"""Compute the winner of a game of Hex / Polygon (CON-TAC-TIX).

Two players place stones on a parallelogram of hexagonal fields.
Player ``O`` plays from top to bottom, player ``X`` plays from left to
right.  The first player to connect their two assigned sides wins.
"""


class ConnectGame:
    def __init__(self, board):
        self.board = [
            row
            for row in (line.strip().split() for line in board.splitlines())
            if row
        ]

    def get_winner(self):
        for player in ("O", "X"):
            if self._reaches_opposite_side(player):
                return player
        return ""

    def _reaches_opposite_side(self, player):
        if not self.board:
            return False
        height = len(self.board)

        if player == "O":
            frontier = [
                (0, c) for c, cell in enumerate(self.board[0]) if cell == player
            ]

            def is_goal(r, _c):
                return r == height - 1
        else:
            frontier = [
                (r, 0) for r, row in enumerate(self.board) if row[0] == player
            ]

            def is_goal(_r, c):
                return c == len(self.board[r]) - 1

        seen = set(frontier)
        while frontier:
            r, c = frontier.pop()
            if is_goal(r, c):
                return True
            for n_r, n_c in self._neighbors(r, c):
                if (n_r, n_c) not in seen and self.board[n_r][n_c] == player:
                    seen.add((n_r, n_c))
                    frontier.append((n_r, n_c))
        return False

    def _neighbors(self, r, c):
        for n_r, n_c in (
            (r, c - 1),
            (r, c + 1),
            (r - 1, c),
            (r - 1, c + 1),
            (r + 1, c - 1),
            (r + 1, c),
        ):
            if 0 <= n_r < len(self.board) and 0 <= n_c < len(self.board[n_r]):
                yield n_r, n_c

